  "uz": {"title": "Reklama moderatsiyasi", "description": "Reklama deb gumon qilingan postlarni Hamjamiyatda paydo bo‘lishidan oldin tekshiring. Yangi postlar va tahrirlar barcha qo‘llab-quvvatlanadigan tillarda tekshiriladi.", "checking_title": "Postingiz tekshirilmoqda", "checking_body": "Postingiz saqlandi va reklama bor-yo‘qligi tekshirilmoqda. U faqat tasdiqlangan taqdirda Hamjamiyatda ko‘rinadi. Holatini Mening postlarim bo‘limida kuzatishingiz mumkin.", "review_title": "Postingiz moderatsiyaga yuborildi", "review_body": "Postingizda reklama bo‘lishi mumkin, shu sababli u moderatorga yuborildi. Tekshiruv davomida u Hamjamiyatda ko‘rinmaydi. Qaror haqida sizga xabar beramiz.", "technical_title": "Postingiz moderator tomonidan tekshirilishi kerak", "technical_body": "Avtomatik tekshiruvni yakunlab bo‘lmadi. Postingiz saqlandi va moderatorga yuborildi. U tekshirilguniga qadar yashirin qoladi.", "approved_title": "Postingiz ma’qullandi", "approved_body": "Postingiz moderatsiyadan o‘tdi va endi Hamjamiyatda ko‘rinadi.", "rejected_title": "Postingiz e’lon qilinmadi", "rejected_body": "Moderator postingizni ma’qullamadi. Sababini ko‘rishingiz, postni tahrirlashingiz va Mening postlarim bo‘limida qayta tekshiruvga yuborishingiz mumkin.", "my_reviews": "Tekshiruvni kutayotgan postlarim", "private_status": "Bu post ma’qullanguniga qadar uni faqat siz va administratorlar ko‘ra oladi.", "status_checking": "Avtomatik tekshiruv", "status_review": "Moderator tekshiruvi kutilmoqda", "status_approved": "Tasdiqlangan", "status_rejected": "Rad etilgan", "status_superseded": "Tahrirlangan versiya bilan almashtirilgan", "status_withdrawn": "Qaytarib olingan", "all": "Barchasi", "all_languages": "Barcha tillar", "search": "Post matni yoki ish IDsi bo‘yicha qidiring", "language": "Post tili", "refresh": "Yangilash", "loading": "Yuklanmoqda…", "empty": "Mos moderatsiya ishlari topilmadi", "load_failed": "Moderatsiya ma’lumotlarini yuklab bo‘lmadi. Qayta urinib ko‘ring.", "unavailable": "Moderatsiya xizmati hozircha mavjud emas. Qoralamangiz saqlandi. Keyinroq qayta urinib ko‘ring.", "save_failed": "Postni saqlab bo‘lmadi. Qoralamangiz saqlandi.", "media_reupload": "Bu biriktirma tasdiqlanmadi. Uni ushbu ilovada qayta yuklang yoki asl fayl bilan yangi post yarating.", "action_failed": "Qarorni saqlab bo‘lmadi. Ish ma’lumotlarini yangilab, qayta urinib ko‘ring.", "conflict": "Bu postni boshqa birov tahrirlagan yoki ko‘rib chiqqan. Qaror qabul qilishdan oldin ma’lumotlarni yangilang.", "action_saved": "Moderatsiya qarori saqlandi", "approve": "Ma’qullash va e’lon qilish", "reject": "E’lon qilishni rad etish", "retry": "Tekshiruvni qayta boshlash", "edit": "Tahrirlash va qayta yuborish", "withdraw": "Postimni o‘chirish", "withdraw_confirm": "Bu post o‘chirilsin va moderatsiyadan qaytarib olinsinmi?", "cancel": "Bekor qilish", "reason": "Muallifga ko‘rsatiladigan sabab", "note": "Moderatorning ichki qaydi", "note_hint": "Faqat administratorlarga ko‘rinadi. Bu qaydni muallifga yuboriladigan bildirishnomaga kiritmang.", "decision": "Moderator qarori", "details": "Ko‘rib chiqish tafsilotlari", "close": "Tafsilotlarni yopish", "case_id": "Ish identifikatori", "version": "Post versiyasi", "created": "Yuborilgan", "reviewed": "Ko‘rib chiqilgan", "author": "Muallif", "anonymous": "Anonim post", "content": "Asl post", "media": "Ilovalar", "no_media": "Ilovalar yo‘q", "media_unavailable": "Bu ilovani avtomatik tekshirib bo‘lmadi. Tasdiqlashdan oldin uni ko‘rib chiqing.", "signals": "Aniqlash signallari", "evidence": "Tegishli parchalar", "visual_evidence": "Rasmlarda aniqlangan matn (AI bahosi)", "risk": "Reklama signali bali", "risk_note": "Bu avtomatik baho, dalil emas. Qaror qabul qilishdan oldin to‘liq kontekstni ko‘rib chiqing.", "engine": "Aniqlash versiyasi", "attempts": "Tekshirish urinishlari", "history": "Qarorlar tarixi", "automatic": "Avtomatik tizim", "notifications": "Bildirishnomani yetkazish", "admin_email": "Administratorga e-pochta", "author_push": "Muallifga push-bildirishnoma", "inbox_note": "Muallifga bildirishnoma e-pochta va push orqali yetkazilishidan qat’i nazar, ilovada saqlanadi.", "delivery_pending": "Navbatga qo‘yildi", "delivery_sending": "Yuborilmoqda", "delivery_sent": "Provayder tomonidan qabul qilindi", "delivery_failed": "Muvaffaqiyatsiz", "delivery_unknown": "Yetkazish natijasi noma’lum", "delivery_skipped": "Yuborilmadi", "retry_delivery": "Muvaffaqiyatsiz yetkazishni qayta urinish", "unknown_delivery_note": "Provayder bu xabarni allaqachon qabul qilgan bo‘lishi mumkin. Takrorlanishning oldini olish uchun avtomatik qayta yuborilmaydi.", "worker": "Avtomatik ishchi jarayon", "worker_ready": "Ishchi jarayon yaqinda faol bo‘lgan", "worker_stale": "Ishchi jarayon yaqinda faollik bildirmagan. Postlar ko‘rib chiqilguniga qadar yashirin qoladi.", "last_worker": "Ishchi jarayonning oxirgi faollik belgisi", "email_destination": "Ko‘rib chiqish haqidagi bildirishnomalar jamil@anacan.az manziliga yuboriladi. Xatlardagi havolalar himoyalangan administrator paneliga olib boradi.", "previous": "Oldingi", "next": "Keyingi", "total": "Mos holatlar", "pending_count": "Ko‘rib chiqilmoqda", "checking_count": "Tekshirilmoqda", "approved_count": "Tasdiqlangan", "rejected_count": "Rad etilgan", "reason_commercial_offer": "Savdo yoki xizmatlarni targ‘ib qilish", "reason_contact_solicitation": "Mijoz jalb qilish uchun ishlatilgan aloqa ma’lumotlari", "reason_referral": "Yo‘llanma, hamkorlik havolasi yoki promo-kod", "reason_recruitment": "Tijoriy yollash yoki daromad olish sxemasi", "reason_external_group": "Tashqi guruh yoki kanalni targ‘ib qilish", "reason_deceptive_promotion": "Yashirin yoki chalg‘ituvchi reklama", "reason_media_review": "Ilovani qo‘lda ko‘rib chiqish zarur", "reason_uncertain": "Kontekstni inson ko‘rib chiqishi zarur", "reason_check_unavailable": "Avtomatik tekshiruv mavjud emas", "reason_not_advertising": "Shaxsiy savol yoki tajriba, reklama emas", "reason_other": "Hamjamiyat qoidalariga oid boshqa muammo", "reason_blocked_account": "Hamjamiyatda post joylash huquqi cheklangan", "event_submitted": "Tekshiruvga yuborildi", "event_automatic_approved": "Avtomatik ravishda tekshiruvdan o‘tdi", "event_flagged": "Moderator ko‘rib chiqishi uchun yuborildi", "event_approved": "Administrator tomonidan tasdiqlandi", "event_rejected": "Administrator tomonidan rad etildi", "event_retry": "Avtomatik tekshiruv qayta so‘raldi", "event_superseded": "Bu tahrir yangiroq tahrir bilan almashtirildi", "event_withdrawn": "Post o‘chirildi", "event_delivery_retry": "Yetkazib bo‘lmadi, qayta navbatga qo‘yildi", "post_changed": "Bu tahrir endi joriy emas. Amal bajarish uchun eng so‘nggi tahrirni oching.", "full_context": "Faqat mahsulot nomi, narx haqidagi savol, shifokor tavsiyasi yoki shaxsiy tajribaning o‘zi reklama ekanini anglatmaydi.", "publication_note": "Tasdiqlash aynan shu tahrirni e’lon qiladi. Matn yoki ilovalarga keyin kiritilgan har qanday o‘zgartirish yana tekshirilishi kerak.", "retry_note": "Avtomatik tekshiruv qayta bajarilayotganida post yashirin qoladi.", "filter_status": "Ko‘rib chiqish holati", "filter_period": "Vaqt oralig‘i", "last_week": "O‘tgan hafta", "last_month": "O‘tgan oy", "all_time": "Barcha vaqt", "copy_case": "Holat ID sini nusxalash", "copied": "Holat ID si nusxalandi"},
  "zh": {"title": "广告审核", "description": "疑似含有广告的内容会在显示于社区前接受审核。所有受支持语言的新帖子和编辑内容都会被检查。", "checking_title": "你的帖子正在接受检查", "checking_body": "你的帖子已保存，正在接受商业推广内容审核。只有审核通过后，才会显示在社区中。你可以在“我的帖子”中查看审核状态。", "review_title": "你的帖子已提交审核", "review_body": "你的帖子可能含有广告，因此已提交给审核员。审核期间，该帖子不会显示在社区中。我们会通知你审核结果。", "technical_title": "你的帖子需要人工审核", "technical_body": "自动检查未能完成。你的帖子已保存并提交给审核员。在审核完成前，它将保持隐藏。", "approved_title": "你的帖子已获批准", "approved_body": "你的帖子已通过审核，现在已显示在社区中。", "rejected_title": "你的帖子未发布", "rejected_body": "审核员未批准你的帖子。你可以在“我的帖子”中查看原因、编辑帖子并重新提交审核。", "my_reviews": "我的待审核帖子", "private_status": "在获得批准前，只有你和管理员可以看到此帖子。", "status_checking": "自动检查", "status_review": "等待审核员审核", "status_approved": "已批准", "status_rejected": "已拒绝", "status_superseded": "已被编辑版本取代", "status_withdrawn": "已撤回", "all": "全部", "all_languages": "所有语言", "search": "搜索帖子内容或案例编号", "language": "帖子语言", "refresh": "刷新", "loading": "正在加载…", "empty": "没有符合条件的审核案例", "load_failed": "无法加载审核信息。请重试。", "unavailable": "审核服务暂时不可用。你的草稿已保留，请稍后重试。", "save_failed": "无法保存帖子。你的草稿已保留。", "media_reupload": "无法验证此附件。请在此应用中重新上传，或使用原始文件创建新帖子。", "action_failed": "无法保存审核决定。请刷新案例后重试。", "conflict": "此帖子已被其他人编辑或审核。请刷新后再作决定。", "action_saved": "审核决定已保存", "approve": "批准并发布", "reject": "拒绝发布", "retry": "重新检查", "edit": "编辑并重新提交", "withdraw": "删除我的帖子", "withdraw_confirm": "要删除此帖子并将其撤回审核吗？", "cancel": "取消", "reason": "向作者显示的原因", "note": "审核员内部备注", "note_hint": "仅管理员可见。请勿在作者通知中包含此备注。", "decision": "审核决定", "details": "审核详情", "close": "关闭详情", "case_id": "案件 ID", "version": "帖子修订版本", "created": "提交时间", "reviewed": "审核时间", "author": "作者", "anonymous": "匿名帖子", "content": "原始帖子", "media": "附件", "no_media": "无附件", "media_unavailable": "无法自动检查此附件。请在批准前进行审核。", "signals": "检测信号", "evidence": "相关摘录", "visual_evidence": "图片中检测到的文字（AI 估算）", "risk": "广告信号评分", "risk_note": "这是自动估算结果，并非证据。请在做出决定前审核完整上下文。", "engine": "检测版本", "attempts": "检查尝试次数", "history": "决定记录", "automatic": "自动系统", "notifications": "通知发送状态", "admin_email": "管理员电子邮件", "author_push": "作者推送通知", "inbox_note": "无论电子邮件和推送通知是否送达，作者通知都会单独保存在应用内。", "delivery_pending": "已加入队列", "delivery_sending": "正在发送", "delivery_sent": "服务提供商已接受", "delivery_failed": "失败", "delivery_unknown": "发送结果未知", "delivery_skipped": "未发送", "retry_delivery": "重试发送失败的通知", "unknown_delivery_note": "服务提供商可能已接受此消息。为避免重复，不会自动重新发送。", "worker": "自动处理程序", "worker_ready": "自动处理程序近期活跃", "worker_stale": "自动处理程序近期未上报状态。帖子在审核完成前将保持隐藏。", "last_worker": "自动处理程序上次上报时间", "email_destination": "审核提醒将发送至 jamil@anacan.az。邮件中包含安全管理面板的链接。", "previous": "上一页", "next": "下一页", "total": "匹配的案例", "pending_count": "等待审核", "checking_count": "检查中", "approved_count": "已批准", "rejected_count": "已拒绝", "reason_commercial_offer": "推销商品或服务", "reason_contact_solicitation": "使用联系方式招揽客户", "reason_referral": "推荐链接、联盟营销链接或促销码", "reason_recruitment": "商业招募或收入计划", "reason_external_group": "推广外部群组或频道", "reason_deceptive_promotion": "隐蔽或误导性推广", "reason_media_review": "附件需要人工审核", "reason_uncertain": "相关语境需要人工审核", "reason_check_unavailable": "自动检查不可用", "reason_not_advertising": "个人问题或经历，并非广告", "reason_other": "其他社区准则问题", "reason_blocked_account": "社区发帖权限受限", "event_submitted": "已提交检查", "event_automatic_approved": "已自动通过", "event_flagged": "已发送给审核员审核", "event_approved": "已由管理员批准", "event_rejected": "已由管理员拒绝", "event_retry": "已再次请求自动检查", "event_superseded": "此版本已被更新的编辑版本取代", "event_withdrawn": "帖子已删除", "event_delivery_retry": "发送失败，已重新加入队列", "post_changed": "此版本已不是当前版本。请打开最新版本进行操作。", "full_context": "仅提及产品名称、询问价格、推荐医生或分享个人经历，并不能判定为广告。", "publication_note": "批准后将发布此确切版本。之后如更改文字或附件，均需再次检查。", "retry_note": "重新进行自动检查期间，帖子将保持隐藏。", "filter_status": "审核状态", "filter_period": "时间范围", "last_week": "上周", "last_month": "上个月", "all_time": "全部时间", "copy_case": "复制案例 ID", "copied": "案例 ID 已复制"},
  "id": {"title": "Moderasi iklan", "description": "Tinjau postingan yang diduga berisi iklan sebelum ditampilkan di Komunitas. Postingan baru dan hasil edit diperiksa dalam setiap bahasa yang didukung.", "checking_title": "Postingan Anda sedang diperiksa", "checking_body": "Postingan Anda telah disimpan dan sedang diperiksa untuk mengetahui apakah mengandung iklan. Postingan hanya akan terlihat di Komunitas jika disetujui. Anda dapat memantau statusnya di Postingan saya.", "review_title": "Postingan Anda telah dikirim untuk dimoderasi", "review_body": "Postingan Anda mungkin berisi iklan, sehingga telah dikirim kepada moderator. Postingan tidak terlihat di Komunitas selama menunggu peninjauan. Kami akan memberi tahu Anda tentang keputusannya.", "technical_title": "Postingan Anda perlu ditinjau moderator", "technical_body": "Pemeriksaan otomatis tidak dapat diselesaikan. Postingan Anda telah disimpan dan dikirim kepada moderator. Postingan akan tetap disembunyikan hingga selesai ditinjau.", "approved_title": "Postingan Anda telah disetujui", "approved_body": "Postingan Anda telah lolos moderasi dan kini terlihat di Komunitas.", "rejected_title": "Postingan Anda tidak dipublikasikan", "rejected_body": "Moderator tidak menyetujui postingan Anda. Anda dapat melihat alasannya, mengedit postingan, dan mengirimkannya untuk ditinjau kembali di Postingan saya.", "my_reviews": "Postingan saya yang menunggu peninjauan", "private_status": "Hanya Anda dan administrator yang dapat melihat postingan ini hingga disetujui.", "status_checking": "Pemeriksaan otomatis", "status_review": "Menunggu moderator", "status_approved": "Disetujui", "status_rejected": "Ditolak", "status_superseded": "Digantikan oleh hasil edit", "status_withdrawn": "Ditarik", "all": "Semua", "all_languages": "Semua bahasa", "search": "Cari teks postingan atau ID kasus", "language": "Bahasa postingan", "refresh": "Muat ulang", "loading": "Memuat…", "empty": "Tidak ada kasus moderasi yang cocok", "load_failed": "