  "hi": {"title": "विज्ञापन मॉडरेशन", "description": "संदिग्ध विज्ञापन के कम्युनिटी में दिखाई देने से पहले उसकी समीक्षा करें। हर समर्थित भाषा में नई पोस्ट और संपादनों की जाँच की जाती है।", "checking_title": "आपकी पोस्ट की जाँच हो रही है", "checking_body": "आपकी पोस्ट सहेज ली गई है और विज्ञापन सामग्री के लिए उसकी जाँच की जा रही है। स्वीकृत होने पर ही वह कम्युनिटी में दिखाई देगी। आप 'मेरी पोस्ट' में उसकी स्थिति देख सकते हैं।", "review_title": "आपकी पोस्ट मॉडरेशन के लिए भेज दी गई है", "review_body": "आपकी पोस्ट में विज्ञापन हो सकता है, इसलिए इसे मॉडरेटर के पास भेजा गया है। समीक्षा लंबित रहने तक यह कम्युनिटी में दिखाई नहीं देगी। निर्णय होने पर हम आपको सूचित करेंगे।", "technical_title": "आपकी पोस्ट की मॉडरेटर द्वारा समीक्षा ज़रूरी है", "technical_body": "स्वचालित जाँच पूरी नहीं हो सकी। आपकी पोस्ट सहेज ली गई है और मॉडरेटर के पास भेज दी गई है। समीक्षा होने तक यह छिपी रहेगी।", "approved_title": "आपकी पोस्ट स्वीकृत हो गई है", "approved_body": "आपकी पोस्ट मॉडरेशन में स्वीकृत हो गई है और अब कम्युनिटी में दिखाई दे रही है।", "rejected_title": "आपकी पोस्ट प्रकाशित नहीं हुई", "rejected_body": "मॉडरेटर ने आपकी पोस्ट को स्वीकृत नहीं किया। आप मेरी पोस्ट में इसका कारण देख सकते हैं, पोस्ट संपादित कर सकते हैं और इसे दोबारा समीक्षा के लिए भेज सकते हैं।", "my_reviews": "समीक्षा की प्रतीक्षा में मेरी पोस्ट", "private_status": "स्वीकृत होने तक केवल आप और एडमिनिस्ट्रेटर ही यह पोस्ट देख सकते हैं।", "status_checking": "स्वचालित जाँच", "status_review": "मॉडरेटर की प्रतीक्षा में", "status_approved": "स्वीकृत", "status_rejected": "अस्वीकृत", "status_superseded": "संपादन से बदली गई", "status_withdrawn": "वापस ली गई", "all": "सभी", "all_languages": "सभी भाषाएँ", "search": "पोस्ट का टेक्स्ट या केस ID खोजें", "language": "पोस्ट की भाषा", "refresh": "रीफ़्रेश करें", "loading": "लोड हो रहा है…", "empty": "मॉडरेशन का कोई मिलता-जुलता मामला नहीं मिला", "load_failed": "मॉडरेशन लोड नहीं हो सका। कृपया फिर से कोशिश करें।", "unavailable": "मॉडरेशन सेवा अभी उपलब्ध नहीं है। आपका ड्राफ़्ट सुरक्षित रखा गया है। कृप